// 1. Intercept & Normalize Raw/Malformed MoE Tool Payloads
const rawText = $input.item.json.output || $input.item.json.text || "";
let toolCalls = [];

// Case 1: Model used native standard schema structures
if ($input.item.json.message?.tool_calls) {
    toolCalls = $input.item.json.message.tool_calls;
} 
// Case 2: Model embedded raw structural markdown json strings
else if (rawText.includes("```json")) {
    try {
        const jsonMatch = rawText.match(/```json\s*([\s\S]*?)\s*```/);
        if (jsonMatch && jsonMatch[1]) {
            const parsed = JSON.parse(jsonMatch[1].trim());
            toolCalls = Array.isArray(parsed) ? parsed : [parsed];
        }
    } catch (e) {}
}
// Case 3: Naked unescaped json strings
else if (rawText.trim().startsWith("{") || rawText.trim().startsWith("[")) {
    try {
        const parsed = JSON.parse(rawText.trim());
        toolCalls = Array.isArray(parsed) ? parsed : [parsed];
    } catch (e) {}
}

// Enforce concrete, strictly structured fields required by engines
const normalizedTools = toolCalls.map((call, idx) => {
    const name = call.function?.name || call.name || call.tool || "unknown_tool";
    let args = call.function?.arguments || call.arguments || call.parameters || {};

    if (typeof args === 'string') {
        try { args = JSON.parse(args); } catch(e) {}
    }

    return {
        id: call.id || `call_moe_${idx}_${Date.now()}`,
        type: "function",
        function: {
            name: name,
            arguments: JSON.stringify(args)
        }
    };
});

return {
    json: {
        original_text: rawText,
        has_tool_call: normalizedTools.length > 0,
        tool_calls: normalizedTools
    }
};

// Simulate standard sub-tool execution (Replace this node with actual production API hits)
const toolName = $('Intercept & Normalize JSON').item.json.tool_calls[0].function.name;
const rawArgs = $('Intercept & Normalize JSON').item.json.tool_calls[0].function.arguments;
const parsedArgs = JSON.parse(rawArgs);

return {
    json: {
        status: "success",
        executed_tool: toolName,
        processed_at: new Date().toISOString(),
        mocked_return_data: {
            message: `Successfully executed ${toolName}`,
            received_inputs: parsedArgs
        }
    }
};

// Wrap execution frame contexts into unified structures models natively read
const originalToolContext = $('Intercept & Normalize JSON').item.json.tool_calls[0];
const executionResult = $input.item.json;

return {
    json: {
        role: "tool",
        tool_call_id: originalToolContext.id,
        name: originalToolContext.function.name,
        content: JSON.stringify(executionResult)
    }
};
